<script setup lang="ts">
import {ref,onMounted} from 'vue';
import {useRoute} from 'vue-router';
import type {Page,Usage,Derivation,QuestionVersion} from '@survey/shared';
import {api} from '../api';
import {queryPage} from '../library-client';
const route=useRoute(),id=String(route.params.questionId),versionId=ref(''),kind=ref('references'),rows=ref<(Usage|Derivation)[]>([]),versions=ref<QuestionVersion[]>([]),versionCursor=ref<string|null>(null),cursor=ref<string|null>(null),busy=ref(false),error=ref('');
async function load(more=false){busy.value=true;error.value='';try{const p=await api<Page<Usage|Derivation>>(`/questions/${id}/usage`+queryPage({kind:kind.value,versionId:versionId.value||undefined,limit:'20',cursor:more?cursor.value??undefined:undefined}));rows.value=more?[...rows.value,...p.items]:p.items;cursor.value=p.nextCursor;}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function loadVersions(more=false){try{const p=await api<Page<QuestionVersion>>(`/questions/${id}/versions`+queryPage({limit:'20',cursor:more?versionCursor.value??undefined:undefined}));versions.value=more?[...versions.value,...p.items]:p.items;versionCursor.value=p.nextCursor;}catch(e){error.value=(e as Error).message;}}
onMounted(async()=>{await loadVersions();await load();});
</script>
<template><section class="narrow library-usage"><RouterLink class="back" :to="`/questions/${id}${route.query.shared?'?shared=1':''}`">← 返回题目</RouterLink><h1 tabindex="-1">题目使用情况</h1><p class="muted">按具体正式版本区分草稿、当前发布和历史使用。每份问卷只显示一次。</p><div class="panel"><label for="usage-version">正式版本</label><select id="usage-version" v-model="versionId" :disabled="busy" @change="load()"><option value="">全部版本</option><option v-for="v in versions" :key="v.id" :value="v.id">v{{v.version}} · {{v.content.title}}</option></select><button v-if="versionCursor" class="quiet" @click="loadVersions(true)">加载更多版本选项</button><label for="usage-kind">查看范围</label><select id="usage-kind" v-model="kind" :disabled="busy" @change="load()"><option value="references">直接引用</option><option v-if="!route.query.shared" value="derivations">派生题（仅作者）</option></select></div>
<p v-if="error" role="alert" class="error">{{error}} <button class="quiet" @click="load()">重新读取</button></p><p v-if="busy" role="status" aria-busy="true">正在核对使用情况…</p><p v-if="!busy&&!rows.length&&!error" class="panel">当前筛选范围没有使用记录。</p>
<ul class="survey-list"><li v-for="(row,index) in rows" :key="index" class="panel"><template v-if="'versions' in row"><h2 v-if="'title' in row"><RouterLink :to="row.managePath">{{row.title}}</RouterLink></h2><h2 v-else>{{row.username}}的问卷</h2><p class="muted">使用编号：{{row.surveyNumber}}</p><p>{{row.isDraft?'有草稿引用 · ':''}}{{row.isCurrent?'有当前发布引用':row.onlyHistorical?'仅历史使用':'未在当前发布中使用'}}</p><ul><li v-for="v in row.versions" :key="v.versionId">题目 v{{v.version}}：{{[v.isDraft?'草稿':'',v.isCurrent?'当前发布':'',v.hasHistorical?'历史发布':''].filter(Boolean).join('、')}}</li></ul></template><template v-else><h2>{{row.ownerUsername}}的派生题</h2><p>源版本：v{{versions.find(v=>v.id===row.sourceVersionId)?.version??'较早版本'}} · 创建于 {{new Date(row.createdAt).toLocaleString('zh-CN')}}</p><p class="muted">派生单独维护，不计入原题直接引用；此记录不授予派生正文访问权。</p></template></li></ul><button v-if="cursor" class="secondary" :disabled="busy" @click="load(true)">加载更多使用记录</button></section></template>
